<?php namespace App\Filament\Resources\WorkOrders\Pages; use App\Filament\Resources\WorkOrders\WorkOrderResource; use Filament\Resources\Pages\CreateRecord; final class CreateWorkOrder extends CreateRecord { protected static string $resource=WorkOrderResource::class; protected function mutateFormDataBeforeCreate(array $data): array { $tenant=$data['tenant_id']??null; $last=\App\Modules\Maintenance\Domain\Models\WorkOrder::query()->where('tenant_id',$tenant)->orderByDesc('created_at')->value('number'); $seq=$last && preg_match('/(\d+)$/',$last,$m)?((int)$m[1]+1):1; $data['number']='OS-'.str_pad((string)$seq,6,'0',STR_PAD_LEFT); return $data; } }
